",
  "rtl/if_stage.sv": "module if_stage (
    input  logic        clk,
    input  logic        rst_n,
    input  logic        stall,
    input  logic        flush,
    input  logic        redirect,
    input  logic [31:0] redirect_target,
    input  logic [31:0] imem_rdata,
    output logic [31:0] imem_addr,
    output logic        if_valid,
    output logic [31:0] if_pc,
    output logic [31:0] if_pc4,
    output logic [31:0] if_instr
);

    logic [31:0] pc;
    logic [31:0] ifid_pc;
    logic [31:0] ifid_pc4;
    logic [31:0] ifid_instr;
    logic        ifid_valid;

    assign imem_addr = pc;

    assign if_valid = ifid_valid;
    assign if_pc    = ifid_pc;
    assign if_pc4   = ifid_pc4;
    assign if_instr = ifid_instr;

    always_ff @(posedge clk) begin
        if (!rst_n) begin
            pc         <= 32'h0000_0000;
            ifid_valid <= 1'b0;
            ifid_pc    <= 32'h0000_0000;
            ifid_pc4   <= 32'h0000_0000;
            ifid_instr <= 32'h0000_0000;
        end else if (redirect) begin
            pc         <= redirect_target;
            ifid_valid <= 1'b0;
            ifid_pc    <= 32'h0000_0000;
            ifid_pc4   <= 32'h0000_0000;
            ifid_instr <= 32'h0000_0000;
        end else if (stall) begin
            pc         <= pc;
            ifid_valid <= ifid_valid;
            ifid_pc    <= ifid_pc;
            ifid_pc4   <= ifid_pc4;
            ifid_instr <= ifid_instr;
        end else if (flush) begin
            pc         <= pc + 32'd4;
            ifid_valid <= 1'b0;
            ifid_pc    <= pc;
            ifid_pc4   <= pc + 32'd4;
            ifid_instr <= imem_rdata;
        end else begin
            pc         <= pc + 32'd4;
            ifid_valid <= 1'b1;
            ifid_pc    <= pc;
            ifid_pc4   <= pc + 32'd4;
            ifid_instr <= imem_rdata;
        end
    end

endmodule
",
  "rtl/id_stage.sv": "module id_stage (
    input  logic        clk,
    input  logic        rst_n,
    input  logic        flush,
    input  logic        if_valid,
    input  logic [31:0] if_pc,
    input  logic [31:0] if_pc4,
    input  logic [31:0] if_instr,
    input  logic        wb_we,
    input  logic [4:0]  wb_rd,
    input  logic [31:0] wb_data,
    input  logic [4:0]  dbg_reg_addr,
    output logic [31:0] dbg_reg_data,
    output logic [31:0] x10_data,
    output logic        id_valid,
    output logic [4:0]  id_rs1,
    output logic [4:0]  id_rs2,
    output logic        id_uses_rs1,
    output logic        id_uses_rs2,
    output logic        id_ecall,
    output logic        id_ex_valid,
    output logic [31:0] id_ex_pc,
    output logic [31:0] id_ex_pc4,
    output logic [31:0] id_ex_instr,
    output logic [31:0] id_ex_rs1_data,
    output logic [31:0] id_ex_rs2_data,
    output logic [4:0]  id_ex_rs1,
    output logic [4:0]  id_ex_rs2,
    output logic [4:0]  id_ex_rd,
    output logic [31:0] id_ex_imm,
    output logic [3:0]  id_ex_alu_op,
    output logic [1:0]  id_ex_alu_a_sel,
    output logic        id_ex_alu_b_sel,
    output logic        id_ex_reg_write,
    output logic        id_ex_mem_read,
    output logic        id_ex_mem_write,
    output logic [2:0]  id_ex_mem_size,
    output logic [1:0]  id_ex_wb_sel,
    output logic [3:0]  id_ex_branch,
    output logic [1:0]  id_ex_jump,
    output logic        id_ex_is_ecall
);

    localparam logic [3:0] ALU_ADD  = 4'd0;
    localparam logic [3:0] ALU_SUB  = 4'd1;
    localparam logic [3:0] ALU_SLL  = 4'd2;
    localparam logic [3:0] ALU_SLT  = 4'd3;
    localparam logic [3:0] ALU_SLTU = 4'd4;
    localparam logic [3:0] ALU_XOR  = 4'd5;
    localparam logic [3:0] ALU_SRL  = 4'd6;
    localparam logic [3:0] ALU_SRA  = 4'd7;
    localparam logic [3:0] ALU_OR   = 4'd8;
    localparam logic [3:0] ALU_AND  = 4'd9;

    localparam logic [1:0] A_RS1  = 2'd0;
    localparam logic [1:0] A_PC   = 2'd1;
    localparam logic [1:0] A_ZERO = 2'd2;

    localparam logic [1:0] WB_ALU  = 2'd0;
    localparam logic [1:0] WB_LOAD = 2'd1;
    localparam logic [1:0] WB_PC4  = 2'd2;

    localparam logic [3:0] BR_NONE = 4'd0;
    localparam logic [3:0] BR_BEQ  = 4'd1;
    localparam logic [3:0] BR_BNE  = 4'd2;
    localparam logic [3:0] BR_BLT  = 4'd3;
    localparam logic [3:0] BR_BGE  = 4'd4;
    localparam logic [3:0] BR_BLTU = 4'd5;
    localparam logic [3:0] BR_BGEU = 4'd6;

    localparam logic [1:0] JMP_NONE = 2'd0;
    localparam logic [1:0] JMP_JAL  = 2'd1;
    localparam logic [1:0] JMP_JALR = 2'd2;

    logic [31:0] regs [1:31];

    logic [31:0] rs1_data;
    logic [31:0] rs2_data;

    logic [6:0]  opcode;
    logic [2:0]  funct3;
    logic [6:0]  funct7;
    logic [4:0]  rs1;
    logic [4:0]  rs2;
    logic [4:0]  rd;

    logic [31:0] imm_i;
    logic [31:0] imm_s;
    logic [31:0] imm_b;
    logic [31:0] imm_u;
    logic [31:0] imm_j;
    logic [31:0] imm;

    logic        dec_uses_rs1;
    logic        dec_uses_rs2;
    logic        dec_ecall;
    logic [31:0] dec_imm;
    logic [3:0]  dec_alu_op;
    logic [1:0]  dec_alu_a_sel;
    logic        dec_alu_b_sel;
    logic        dec_reg_write;
    logic        dec_mem_read;
    logic        dec_mem_write;
    logic [2:0]  dec_mem_size;
    logic [1:0]  dec_wb_sel;
    logic [3:0]  dec_branch;
    logic [1:0]  dec_jump;

    assign opcode = if_instr[6:0];
    assign funct3 = if_instr[14:12];
    assign funct7 = if_instr[31:25];
    assign rs1    = if_instr[19:15];
    assign rs2    = if_instr[24:20];
    assign rd     = if_instr[11:7];

    assign imm_i = {{20{if_instr[31]}}, if_instr[31:20]};
    assign imm_s = {{20{if_instr[31]}}, if_instr[31:25], if_instr[11:7]};
    assign imm_b = {{19{if_instr[31]}}, if_instr[31], if_instr[7], if_instr[30:25], if_instr[11:8], 1'b0};
    assign imm_u = {if_instr[31:12], 12'b0};
    assign imm_j = {{11{if_instr[31]}}, if_instr[31], if_instr[19:12], if_instr[20], if_instr[30:21], 1'b0};

    always_comb begin
        dec_uses_rs1   = 1'b0;
        dec_uses_rs2   = 1'b0;
        dec_ecall      = 1'b0;
        dec_imm        = 32'b0;
        dec_alu_op     = ALU_ADD;
        dec_alu_a_sel  = A_RS1;
        dec_alu_b_sel  = 1'b0;
        dec_reg_write  = 1'b0;
        dec_mem_read   = 1'b0;
        dec_mem_write  = 1'b0;
        dec_mem_size   = funct3;
        dec_wb_sel     = WB_ALU;
        dec_branch     = BR_NONE;
        dec_jump       = JMP_NONE;

        case (opcode)
            7'b0110011: begin
                dec_uses_rs1  = 1'b1;
                dec_uses_rs2  = 1'b1;
                dec_reg_write = 1'b1;
                dec_alu_a_sel = A_RS1;
                dec_alu_b_sel = 1'b0;
                dec_wb_sel    = WB_ALU;
                case (funct3)
                    3'b000: dec_alu_op = funct7[5] ? ALU_SUB : ALU_ADD;
                    3'b001: dec_alu_op = ALU_SLL;
                    3'b010: dec_alu_op = ALU_SLT;
                    3'b011: dec_alu_op = ALU_SLTU;
                    3'b100: dec_alu_op = ALU_XOR;
                    3'b101: dec_alu_op = funct7[5] ? ALU_SRA : ALU_SRL;
                    3'b110: dec_alu_op = ALU_OR;
                    3'b111: dec_alu_op = ALU_AND;
                    default: dec_alu_op = ALU_ADD;
                endcase
            end
            7'b0010011: begin
                dec_uses_rs1  = 1'b1;
                dec_reg_write = 1'b1;
                dec_imm       = imm_i;
                dec_alu_a_sel = A_RS1;
                dec_alu_b_sel = 1'b1;
                dec_wb_sel    = WB_ALU;
                case (funct3)
                    3'b000: dec_alu_op = ALU_ADD;
                    3'b001: dec_alu_op = ALU_SLL;
                    3'b010: dec_alu_op = ALU_SLT;
                    3'b011: dec_alu_op = ALU_SLTU;
                    3'b100: dec_alu_op = ALU_XOR;
                    3'b101: dec_alu_op = funct7[5] ? ALU_SRA : ALU_SRL;
                    3'b110: dec_alu_op = ALU_OR;
                    3'b111: dec_alu_op = ALU_AND;
                    default: dec_alu_op = ALU_ADD;
                endcase
            end
            7'b0000011: begin
                dec_uses_rs1  = 1'b1;
                dec_reg_write = 1'b1;
                dec_mem_read  = 1'b1;
                dec_imm       = imm_i;
                dec_alu_op    = ALU_ADD;
                dec_alu_a_sel = A_RS1;
                dec_alu_b_sel = 1'b1;
                dec_wb_sel    = WB_LOAD;
                dec_mem_size  = funct3;
            end
            7'b0100011: begin
                dec_uses_rs1  = 1'b1;
                dec_uses_rs2  = 1'b1;
                dec_mem_write = 1'b1;
                dec_imm       = imm_s;
                dec_alu_op    = ALU_ADD;
                dec_alu_a_sel = A_RS1;
                dec_alu_b_sel = 1'b1;
                dec_mem_size  = funct3;
            end
            7'b1100011: begin
                dec_uses_rs1  = 1'b1;
                dec_uses_rs2  = 1'b1;
                dec_imm       = imm_b;
                dec_alu_op    = ALU_ADD;
                dec_alu_a_sel = A_PC;
                dec_alu_b_sel = 1'b1;
                case (funct3)
                    3'b000: dec_branch = BR_BEQ;
                    3'b001: dec_branch = BR_BNE;
                    3'b100: dec_branch = BR_BLT;
                    3'b101: dec_branch = BR_BGE;
                    3'b110: dec_branch = BR_BLTU;
                    3'b111: dec_branch = BR_BGEU;
                    default: dec_branch = BR_NONE;
                endcase
            end
            7'b1101111: begin
                dec_reg_write = 1'b1;
                dec_imm       = imm_j;
                dec_alu_op    = ALU_ADD;
                dec_alu_a_sel = A_PC;
                dec_alu_b_sel = 1'b1;
                dec_wb_sel    = WB_PC4;
                dec_jump      = JMP_JAL;
            end
            7'b1100111: begin
                dec_uses_rs1  = 1'b1;
                dec_reg_write = 1'b1;
                dec_imm       = imm_i;
                dec_alu_op    = ALU_ADD;
                dec_alu_a_sel = A_RS1;
                dec_alu_b_sel = 1'b1;
                dec_wb_sel    = WB_PC4;
                dec_jump      = JMP_JALR;
            end
            7'b0110111: begin
                dec_reg_write = 1'b1;
                dec_imm       = imm_u;
                dec_alu_op    = ALU_ADD;
                dec_alu_a_sel = A_ZERO;
                dec_alu_b_sel = 1'b1;
                dec_wb_sel    = WB_ALU;
            end
            7'b0010111: begin
                dec_reg_write = 1'b1;
                dec_imm       = imm_u;
                dec_alu_op    = ALU_ADD;
                dec_alu_a_sel = A_PC;
                dec_alu_b_sel = 1'b1;
                dec_wb_sel    = WB_ALU;
            end
            7'b1110011: begin
                if (if_instr == 32'h0000_0073) begin
                    dec_ecall = 1'b1;
                end
            end
            default: begin
            end
        endcase
    end

    assign id_valid     = if_valid;
    assign id_rs1       = rs1;
    assign id_rs2       = rs2;
    assign id_uses_rs1  = if_valid & dec_uses_rs1;
    assign id_uses_rs2  = if_valid & dec_uses_rs2;
    assign id_ecall     = if_valid & dec_ecall;

    always_comb begin
        rs1_data = 32'b0;
        if (rs1 != 5'd0) begin
            if (wb_we && (wb_rd == rs1) && (wb_rd != 5'd0))
                rs1_data = wb_data;
            else
                rs1_data = regs[rs1];
        end
    end

    always_comb begin
        rs2_data = 32'b0;
        if (rs2 != 5'd0) begin
            if (wb_we && (wb_rd == rs2) && (wb_rd != 5'd0))
                rs2_data = wb_data;
            else
                rs2_data = regs[rs2];
        end
    end

    always_comb begin
        dbg_reg_data = 32'b0;
        if (dbg_reg_addr != 5'd0)
            dbg_reg_data = regs[dbg_reg_addr];
    end

    assign x10_data = regs[10];

    always_ff @(posedge clk) begin
        if (!rst_n) begin
            for (int i = 1; i < 32; i++) begin
                regs[i] <= 32'b0;
            end
        end else if (wb_we && (wb_rd != 5'd0)) begin
            regs[wb_rd] <= wb_data;
        end
    end

    always_ff @(posedge clk) begin
        if (!rst_n) begin
            id_ex_valid      <= 1'b0;
            id_ex_pc         <= 32'b0;
            id_ex_pc4        <= 32'b0;
            id_ex_instr      <= 32'b0;
            id_ex_rs1_data   <= 32'b0;
            id_ex_rs2_data   <= 32'b0;
            id_ex_rs1        <= 5'b0;
            id_ex_rs2        <= 5'b0;
            id_ex_rd         <= 5'b0;
            id_ex_imm        <= 32'b0;
            id_ex_alu_op     <= ALU_ADD;
            id_ex_alu_a_sel  <= A_RS1;
            id_ex_alu_b_sel  <= 1'b0;
            id_ex_reg_write  <= 1'b0;
            id_ex_mem_read   <= 1'b0;
            id_ex_mem_write  <= 1'b0;
            id_ex_mem_size   <= 3'b0;
            id_ex_wb_sel     <= WB_ALU;
            id_ex_branch     <= BR_NONE;
            id_ex_jump       <= JMP_NONE;
            id_ex_is_ecall   <= 1'b0;
        end else if (flush) begin
            id_ex_valid      <= 1'b0;
            id_ex_pc         <= 32'b0;
            id_ex_pc4        <= 32'b0;
            id_ex_instr      <= 32'b0;
            id_ex_rs1_data   <= 32'b0;
            id_ex_rs2_data   <= 32'b0;
            id_ex_rs1        <= 5'b0;
            id_ex_rs2        <= 5'b0;
            id_ex_rd         <= 5'b0;
            id_ex_imm        <= 32'b0;
            id_ex_alu_op     <= ALU_ADD;
            id_ex_alu_a_sel  <= A_RS1;
            id_ex_alu_b_sel  <= 1'b0;
            id_ex_reg_write  <= 1'b0;
            id_ex_mem_read   <= 1'b0;
            id_ex_mem_write  <= 1'b0;
            id_ex_mem_size   <= 3'b0;
            id_ex_wb_sel     <= WB_ALU;
            id_ex_branch     <= BR_NONE;
            id_ex_jump       <= JMP_NONE;
            id_ex_is_ecall   <= 1'b0;
        end else begin
            id_ex_valid      <= if_valid;
            id_ex_pc         <= if_pc;
            id_ex_pc4        <= if_pc4;
            id_ex_instr      <= if_instr;
            id_ex_rs1_data   <= rs1_data;
            id_ex_rs2_data   <= rs2_data;
            id_ex_rs1        <= rs1;
            id_ex_rs2        <= rs2;
            id_ex_rd         <= rd;
            id_ex_imm        <= dec_imm;
            id_ex_alu_op     <= dec_alu_op;
            id_ex_alu_a_sel  <= dec_alu_a_sel;
            id_ex_alu_b_sel  <= dec_alu_b_sel;
            id_ex_reg_write  <= dec_reg_write;
            id_ex_mem_read   <= dec_mem_read;
            id_ex_mem_write  <= dec_mem_write;
            id_ex_mem_size   <= dec_mem_size;
            id_ex_wb_sel     <= dec_wb_sel;
            id_ex_branch     <= dec_branch;
            id_ex_jump       <= dec_jump;
            id_ex_is_ecall   <= dec_ecall;
        end
    end

endmodule
",
  "rtl/ex_stage.sv": "module ex_stage (
    input  logic        clk,
    input  logic        rst_n,
    input  logic [1:0]  fwd_a_sel,
    input  logic [1:0]  fwd_b_sel,
    input  logic [31:0] wb_data,
    input  logic        id_ex_valid,
    input  logic [31:0] id_ex_pc,
    input  logic [31:0] id_ex_pc4,
    input  logic [31:0] id_ex_instr,
    input  logic [31:0] id_ex_rs1_data,
    input  logic [31:0] id_ex_rs2_data,
    input  logic [4:0]  id_ex_rs1,
    input  logic [4:0]  id_ex_rs2,
    input  logic [4:0]  id_ex_rd,
    input  logic [31:0] id_ex_imm,
    input  logic [3:0]  id_ex_alu_op,
    input  logic [1:0]  id_ex_alu_a_sel,
    input  logic        id_ex_alu_b_sel,
    input  logic        id_ex_reg_write,
    input  logic        id_ex_mem_read,
    input  logic        id_ex_mem_write,
    input  logic [2:0]  id_ex_mem_size,
    input  logic [1:0]  id_ex_wb_sel,
    input  logic [3:0]  id_ex_branch,
    input  logic [1:0]  id_ex_jump,
    input  logic        id_ex_is_ecall,
    output logic        ex_mem_valid,
    output logic [31:0] ex_mem_pc4,
    output logic [4:0]  ex_mem_rd,
    output logic [31:0] ex_mem_alu_result,
    output logic [31:0] ex_mem_rs2_data,
    output logic [4:0]  ex_mem_rs2,
    output logic        ex_mem_reg_write,
    output logic        ex_mem_mem_read,
    output logic        ex_mem_mem_write,
    output logic [2:0]  ex_mem_mem_size,
    output logic [1:0]  ex_mem_wb_sel,
    output logic        ex_mem_is_ecall,
    output logic        redirect,
    output logic [31:0] redirect_target
);

    localparam logic [3:0] ALU_ADD  = 4'd0;
    localparam logic [3:0] ALU_SUB  = 4'd1;
    localparam logic [3:0] ALU_SLL  = 4'd2;
    localparam logic [3:0] ALU_SLT  = 4'd3;
    localparam logic [3:0] ALU_SLTU = 4'd4;
    localparam logic [3:0] ALU_XOR  = 4'd5;
    localparam logic [3:0] ALU_SRL  = 4'd6;
    localparam logic [3:0] ALU_SRA  = 4'd7;
    localparam logic [3:0] ALU_OR   = 4'd8;
    localparam logic [3:0] ALU_AND  = 4'd9;

    localparam logic [1:0] A_RS1  = 2'd0;
    localparam logic [1:0] A_PC   = 2'd1;
    localparam logic [1:0] A_ZERO = 2'd2;

    localparam logic [3:0] BR_NONE = 4'd0;
    localparam logic [3:0] BR_BEQ  = 4'd1;
    localparam logic [3:0] BR_BNE  = 4'd2;
    localparam logic [3:0] BR_BLT  = 4'd3;
    localparam logic [3:0] BR_BGE  = 4'd4;
    localparam logic [3:0] BR_BLTU = 4'd5;
    localparam logic [3:0] BR_BGEU = 4'd6;

    localparam logic [1:0] JMP_NONE = 2'd0;
    localparam logic [1:0] JMP_JAL  = 2'd1;
    localparam logic [1:0] JMP_JALR = 2'd2;

    localparam logic [1:0] WB_ALU  = 2'd0;
    localparam logic [1:0] WB_LOAD = 2'd1;
    localparam logic [1:0] WB_PC4  = 2'd2;

    logic [31:0] rs1_fwd;
    logic [31:0] rs2_fwd;
    logic [31:0] alu_a;
    logic [31:0] alu_b;
    logic [31:0] alu_result;
    logic [31:0] jump_target;
    logic        branch_taken;
    logic        jump_taken;
    logic        redirect_comb;
    logic [31:0] redirect_target_comb;
    logic [31:0] ex_result;

    always_comb begin
        rs1_fwd = id_ex_rs1_data;
        if (fwd_a_sel == 2'b10)
            rs1_fwd = ex_mem_alu_result;
        else if (fwd_a_sel == 2'b01)
            rs1_fwd = wb_data;

        rs2_fwd = id_ex_rs2_data;
        if (fwd_b_sel == 2'b10)
            rs2_fwd = ex_mem_alu_result;
        else if (fwd_b_sel == 2'b01)
            rs2_fwd = wb_data;
    end

    always_comb begin
        case (id_ex_alu_a_sel)
            A_PC:    alu_a = id_ex_pc;
            A_ZERO:  alu_a = 32'd0;
            default: alu_a = rs1_fwd;
        endcase
        alu_b = id_ex_alu_b_sel ? id_ex_imm : rs2_fwd;
    end

    always_comb begin
        case (id_ex_alu_op)
            ALU_ADD:  alu_result = alu_a + alu_b;
            ALU_SUB:  alu_result = alu_a - alu_b;
            ALU_SLL:  alu_result = alu_a << alu_b[4:0];
            ALU_SLT:  alu_result = ($signed(alu_a) < $signed(alu_b)) ? 32'd1 : 32'd0;
            ALU_SLTU: alu_result = (alu_a < alu_b) ? 32'd1 : 32'd0;
            ALU_XOR:  alu_result = alu_a ^ alu_b;
            ALU_SRL:  alu_result = alu_a >> alu_b[4:0];
            ALU_SRA:  alu_result = $signed(alu_a) >>> alu_b[4:0];
            ALU_OR:   alu_result = alu_a | alu_b;
            ALU_AND:  alu_result = alu_a & alu_b;
            default:  alu_result = 32'd0;
        endcase
    end

    always_comb begin
        branch_taken = 1'b0;
        if (id_ex_valid) begin
            case (id_ex_branch)
                BR_BEQ:  branch_taken = (rs1_fwd == rs2_fwd);
                BR_BNE:  branch_taken = (rs1_fwd != rs2_fwd);
                BR_BLT:  branch_taken = ($signed(rs1_fwd) < $signed(rs2_fwd));
                BR_BGE:  branch_taken = ($signed(rs1_fwd) >= $signed(rs2_fwd));
                BR_BLTU: branch_taken = (rs1_fwd < rs2_fwd);
                BR_BGEU: branch_taken = (rs1_fwd >= rs2_fwd);
                default: branch_taken = 1'b0;
            endcase
        end
    end

    always_comb begin
        jump_taken = 1'b0;
        jump_target = 32'd0;
        if (id_ex_valid) begin
            case (id_ex_jump)
                JMP_JAL: begin
                    jump_taken = 1'b1;
                    jump_target = id_ex_pc + id_ex_imm;
                end
                JMP_JALR: begin
                    jump_taken = 1'b1;
                    jump_target = (rs1_fwd + id_ex_imm) & 32'hFFFF_FFFE;
                end
                default: begin
                    jump_taken = 1'b0;
                    jump_target = 32'd0;
                end
            endcase
        end
    end

    always_comb begin
        redirect_comb = 1'b0;
        redirect_target_comb = 32'd0;
        if (id_ex_valid) begin
            if (jump_taken) begin
                redirect_comb = 1'b1;
                redirect_target_comb = jump_target;
            end else if (branch_taken) begin
                redirect_comb = 1'b1;
                redirect_target_comb = id_ex_pc + id_ex_imm;
            end
        end
    end

    assign redirect = redirect_comb;
    assign redirect_target = redirect_target_comb;

    always_comb begin
        if (id_ex_wb_sel == WB_PC4)
            ex_result = id_ex_pc4;
        else
            ex_result = alu_result;
    end

    always_ff @(posedge clk) begin
        if (!rst_n) begin
            ex_mem_valid      <= 1'b0;
            ex_mem_pc4        <= 32'd0;
            ex_mem_rd         <= 5'd0;
            ex_mem_alu_result <= 32'd0;
            ex_mem_rs2_data   <= 32'd0;
            ex_mem_rs2        <= 5'd0;
            ex_mem_reg_write  <= 1'b0;
            ex_mem_mem_read   <= 1'b0;
            ex_mem_mem_write  <= 1'b0;
            ex_mem_mem_size   <= 3'd0;
            ex_mem_wb_sel     <= 2'd0;
            ex_mem_is_ecall   <= 1'b0;
        end else begin
            ex_mem_valid      <= id_ex_valid;
            ex_mem_pc4        <= id_ex_pc4;
            ex_mem_rd         <= id_ex_rd;
            ex_mem_alu_result <= ex_result;
            ex_mem_rs2_data   <= rs2_fwd;
            ex_mem_rs2        <= id_ex_rs2;
            ex_mem_reg_write  <= id_ex_reg_write;
            ex_mem_mem_read   <= id_ex_mem_read;
            ex_mem_mem_write  <= id_ex_mem_write;
            ex_mem_mem_size   <= id_ex_mem_size;
            ex_mem_wb_sel     <= id_ex_wb_sel;
            ex_mem_is_ecall   <= id_ex_is_ecall;
        end
    end

endmodule
",
  "rtl/mem_stage.sv": "module mem_stage (
    input  logic        clk,
    input  logic        rst_n,
    input  logic        halted,
    input  logic [31:0] dmem_rdata,
    input  logic        wb_we,
    input  logic [4:0]  wb_rd,
    input  logic [31:0] wb_data,
    input  logic        ex_mem_valid,
    input  logic [31:0] ex_mem_pc4,
    input  logic [4:0]  ex_mem_rd,
    input  logic [31:0] ex_mem_alu_result,
    input  logic [31:0] ex_mem_rs2_data,
    input  logic [4:0]  ex_mem_rs2,
    input  logic        ex_mem_reg_write,
    input  logic        ex_mem_mem_read,
    input  logic        ex_mem_mem_write,
    input  logic [2:0]  ex_mem_mem_size,
    input  logic [1:0]  ex_mem_wb_sel,
    input  logic        ex_mem_is_ecall,
    output logic        dmem_valid,
    output logic        dmem_we,
    output logic [31:0] dmem_addr,
    output logic [31:0] dmem_wdata,
    output logic [3:0]  dmem_be,
    output logic        mem_wb_valid,
    output logic        mem_wb_reg_write,
    output logic [4:0]  mem_wb_rd,
    output logic [1:0]  mem_wb_wb_sel,
    output logic [31:0] mem_wb_alu_result,
    output logic [31:0] mem_wb_pc4,
    output logic [31:0] mem_wb_load_data,
    output logic        mem_wb_is_ecall
);

    localparam logic [1:0] WB_ALU  = 2'd0;
    localparam logic [1:0] WB_LOAD = 2'd1;
    localparam logic [1:0] WB_PC4  = 2'd2;

    logic        mem_active;
    logic [31:0] store_data;
    logic [31:0] load_data;

    always_comb begin
        store_data = ex_mem_rs2_data;
        if (wb_we && (wb_rd != 5'd0) && (wb_rd == ex_mem_rs2)) begin
            store_data = wb_data;
        end
    end

    always_comb begin
        dmem_valid = rst_n && !halted && ex_mem_valid &&
                     (ex_mem_mem_read || ex_mem_mem_write);
        dmem_we    = ex_mem_mem_write;
        dmem_addr  = ex_mem_alu_result;
        dmem_wdata = store_data;
        dmem_be    = 4'b0000;
        if (ex_mem_mem_write) begin
            case (ex_mem_mem_size)
                3'b000: begin
                    dmem_wdata = {4{store_data[7:0]}};
                    dmem_be    = 4'b0001 << ex_mem_alu_result[1:0];
                end
                3'b001: begin
                    dmem_wdata = {2{store_data[15:0]}};
                    dmem_be    = ex_mem_alu_result[1] ? 4'b1100 : 4'b0011;
                end
                default: begin
                    dmem_wdata = store_data;
                    dmem_be    = 4'b1111;
                end
            endcase
        end
    end

    always_comb begin
        logic [7:0]  byte_data;
        logic [15:0] half_data;
        byte_data = dmem_rdata[{ex_mem_alu_result[1:0], 3'b000} +: 8];
        half_data = dmem_rdata[{ex_mem_alu_result[1], 4'b0000} +: 16];
        case (ex_mem_mem_size)
            3'b000:  load_data = {{24{byte_data[7]}}, byte_data};
            3'b001:  load_data = {{16{half_data[15]}}, half_data};
            3'b100:  load_data = {24'b0, byte_data};
            3'b101:  load_data = {16'b0, half_data};
            default: load_data = dmem_rdata;
        endcase
    end

    always_ff @(posedge clk) begin
        if (!rst_n) begin
            mem_active       <= 1'b0;
            mem_wb_valid     <= 1'b0;
            mem_wb_reg_write <= 1'b0;
            mem_wb_rd        <= 5'd0;
            mem_wb_wb_sel    <= WB_ALU;
            mem_wb_alu_result<= 32'd0;
            mem_wb_pc4       <= 32'd0;
            mem_wb_load_data <= 32'd0;
            mem_wb_is_ecall  <= 1'b0;
        end else if (halted) begin
            mem_active       <= 1'b0;
            mem_wb_valid     <= 1'b0;
            mem_wb_reg_write <= 1'b0;
            mem_wb_rd        <= 5'd0;
            mem_wb_wb_sel    <= WB_ALU;
            mem_wb_alu_result<= 32'd0;
            mem_wb_pc4       <= 32'd0;
            mem_wb_load_data <= 32'd0;
            mem_wb_is_ecall  <= 1'b0;
        end else begin
            mem_wb_valid     <= ex_mem_valid;
            mem_wb_reg_write <= ex_mem_valid && ex_mem_reg_write;
            mem_wb_rd        <= ex_mem_rd;
            mem_wb_wb_sel    <= ex_mem_wb_sel;
            mem_wb_alu_result<= ex_mem_alu_result;
            mem_wb_pc4       <= ex_mem_pc4;
            mem_wb_load_data <= load_data;
            mem_wb_is_ecall  <= ex_mem_valid && ex_mem_is_ecall;
        end
    end

endmodule
",
  "rtl/wb_stage.sv": "module wb_stage (
    input  logic        clk,
    input  logic        rst_n,
    input  logic [31:0] x10_data,
    input  logic        mem_wb_valid,
    input  logic        mem_wb_reg_write,
    input  logic [4:0]  mem_wb_rd,
    input  logic [1:0]  mem_wb_wb_sel,
    input  logic [31:0] mem_wb_alu_result,
    input  logic [31:0] mem_wb_pc4,
    input  logic [31:0] mem_wb_load_data,
    input  logic        mem_wb_is_ecall,
    output logic        wb_we,
    output logic [4:0]  wb_rd,
    output logic [31:0] wb_data,
    output logic        halted,
    output logic [31:0] exit_code
);

    localparam logic [1:0] WB_ALU  = 2'd0;
    localparam logic [1:0] WB_LOAD = 2'd1;
    localparam logic [1:0] WB_PC4  = 2'd2;

    logic [31:0] wb_data_sel;

    always_comb begin
        wb_data_sel = mem_wb_alu_result;
        case (mem_wb_wb_sel)
            WB_ALU:  wb_data_sel = mem_wb_alu_result;
            WB_LOAD: wb_data_sel = mem_wb_load_data;
            WB_PC4:  wb_data_sel = mem_wb_pc4;
            default: wb_data_sel = mem_wb_alu_result;
        endcase
    end

    always_comb begin
        wb_we   = mem_wb_valid && mem_wb_reg_write && (mem_wb_rd != 5'd0) && !halted;
        wb_rd   = mem_wb_rd;
        wb_data = wb_data_sel;
    end

    always_ff @(posedge clk) begin
        if (!rst_n) begin
            halted    <= 1'b0;
            exit_code <= 32'd0;
        end else if (!halted) begin
            if (mem_wb_valid && mem_wb_is_ecall) begin
                halted    <= 1'b1;
                exit_code <= x10_data;
            end
        end
    end

endmodule
",
  "rtl/hazard_unit.sv": "module hazard_unit (
    input  logic       clk,
    input  logic       rst_n,
    input  logic       id_valid,
    input  logic       id_ecall,
    input  logic       id_uses_rs1,
    input  logic       id_uses_rs2,
    input  logic [4:0] id_rs1,
    input  logic [4:0] id_rs2,
    input  logic       ex_valid,
    input  logic       ex_mem_read,
    input  logic [4:0] ex_rd,
    input  logic       redirect,
    input  logic       halted,
    output logic       stall,
    output logic       flush_if_id,
    output logic       flush_id_ex,
    output logic       halt_pending
);

    logic load_use;
    logic ecall_enter;

    always_comb begin
        load_use = 1'b0;
        if (ex_valid && ex_mem_read && (ex_rd != 5'd0) && id_valid) begin
            if ((id_uses_rs1 && (id_rs1 == ex_rd)) ||
                (id_uses_rs2 && (id_rs2 == ex_rd))) begin
                load_use = 1'b1;
            end
        end
    end

    always_comb begin
        ecall_enter = id_valid && id_ecall && !halt_pending && !redirect && !halted;
    end

    always_comb begin
        stall       = load_use && !redirect && !halt_pending && !halted;
        flush_if_id = redirect || halt_pending || halted;
        flush_id_ex = redirect || halt_pending || halted;
    end

    always_ff @(posedge clk) begin
        if (!rst_n) begin
            halt_pending <= 1'b0;
        end else if (halted) begin
            halt_pending <= 1'b0;
        end else if (ecall_enter) begin
            halt_pending <= 1'b1;
        end
    end

endmodule
",
  "rtl/forwarding_unit.sv": "module forwarding_unit (
    input  logic       ex_mem_valid,
    input  logic       ex_mem_reg_write,
    input  logic       ex_mem_mem_read,
    input  logic [4:0] ex_mem_rd,
    input  logic       wb_we,
    input  logic [4:0] wb_rd,
    input  logic [4:0] id_ex_rs1,
    input  logic [4:0] id_ex_rs2,
    output logic [1:0] fwd_a_sel,
    output logic [1:0] fwd_b_sel
);

    logic ex_mem_hit_a;
    logic ex_mem_hit_b;
    logic wb_hit_a;
    logic wb_hit_b;

    assign ex_mem_hit_a = ex_mem_valid && ex_mem_reg_write && !ex_mem_mem_read &&
                          (ex_mem_rd != 5'd0) && (ex_mem_rd == id_ex_rs1);
    assign ex_mem_hit_b = ex_mem_valid && ex_mem_reg_write && !ex_mem_mem_read &&
                          (ex_mem_rd != 5'd0) && (ex_mem_rd == id_ex_rs2);

    assign wb_hit_a = wb_we && (wb_rd != 5'd0) && (wb_rd == id_ex_rs1);
    assign wb_hit_b = wb_we && (wb_rd != 5'd0) && (wb_rd == id_ex_rs2);

    always_comb begin
        if (ex_mem_hit_a) begin
            fwd_a_sel = 2'b10;
        end else if (wb_hit_a) begin
            fwd_a_sel = 2'b01;
        end else begin
            fwd_a_sel = 2'b00;
        end

        if (ex_mem_hit_b) begin
            fwd_b_sel = 2'b10;
        end else if (wb_hit_b) begin
            fwd_b_sel = 2'b01;
        end else begin
            fwd_b_sel = 2'b00;
        end
    end

endmodule
"
}

