  "rtl/wb_stage.sv": "module wb_stage (
    input  logic        clk,
    input  logic        rst_n,
    input  logic [31:0] x10_data,
    input  logic        mem_wb_valid,
    input  logic        mem_wb_reg_write,
    input  logic [4:0]  mem_wb_rd,
    input  logic [1:0]  mem_wb_wb_sel,
    input  logic [31:0] mem_wb_alu_result,
    input  logic [31:0] mem_wb_pc4,
    input  logic [31:0] mem_wb_load_data,
    input  logic        mem_wb_is_ecall,
    output logic        wb_we,
    output logic [4:0]  wb_rd,
    output logic [31:0] wb_data,
    output logic        halted,
    output logic [31:0] exit_code
);

    localparam logic [1:0] WB_ALU  = 2'd0;
    localparam logic [1:0] WB_LOAD = 2'd1;
    localparam logic [1:0] WB_PC4  = 2'd2;

    logic [31:0] wb_data_sel;

    always_comb begin
        wb_data_sel = mem_wb_alu_result;
        case (mem_wb_wb_sel)
            WB_ALU:  wb_data_sel = mem_wb_alu_result;
            WB_LOAD: wb_data_sel = mem_wb_load_data;
            WB_PC4:  wb_data_sel = mem_wb_pc4;
            default: wb_data_sel = mem_wb_alu_result;
        endcase
    end

    always_comb begin
        wb_we   = mem_wb_valid && mem_wb_reg_write && (mem_wb_rd != 5'd0) && !halted;
        wb_rd   = mem_wb_rd;
        wb_data = wb_data_sel;
    end

    always_ff @(posedge clk) begin
        if (!rst_n) begin
            halted    <= 1'b0;
            exit_code <= 32'd0;
        end else if (!halted) begin
            if (mem_wb_valid && mem_wb_is_ecall) begin
                halted    <= 1'b1;
                exit_code <= x10_data;
            end
        end
    end

endmodule
",
  "rtl/hazard_unit.sv": "module hazard_unit (
    input  logic       clk,
    input  logic       rst_n,
    input  logic       id_valid,
    input  logic       id_ecall,
    input  logic       id_uses_rs1,
    input  logic       id_uses_rs2,
    input  logic [4:0] id_rs1,
    input  logic [4:0] id_rs2,
    input  logic       ex_valid,
    input  logic       ex_mem_read,
    input  logic [4:0] ex_rd,
    input  logic       redirect,
    input  logic       halted,
    output logic       stall,
    output logic       flush_if_id,
    output logic       flush_id_ex,
    output logic       halt_pending
);

    logic load_use;
    logic ecall_enter;

    always_comb begin
        load_use = 1'b0;
        if (ex_valid && ex_mem_read && (ex_rd != 5'd0) && id_valid) begin
            if ((id_uses_rs1 && (id_rs1 == ex_rd)) ||
                (id_uses_rs2 && (id_rs2 == ex_rd))) begin
                load_use = 1'b1;
            end
        end
    end

    always_comb begin
        ecall_enter = id_valid && id_ecall && !halt_pending && !redirect && !halted;
    end

    always_comb begin
        stall       = load_use && !redirect && !halt_pending && !halted;
        flush_if_id = redirect || halt_pending || halted;
        flush_id_ex = redirect || halt_pending || halted;
    end

    always_ff @(posedge clk) begin
        if (!rst_n) begin
            halt_pending <= 1'b0;
        end else if (halted) begin
            halt_pending <= 1'b0;
        end else if (ecall_enter) begin
            halt_pending <= 1'b1;
        end
    end

endmodule
",
  "rtl/forwarding_unit.sv": "module forwarding_unit (
    input  logic       ex_mem_valid,
    input  logic       ex_mem_reg_write,
    input  logic       ex_mem_mem_read,
    input  logic [4:0] ex_mem_rd,
    input  logic       wb_we,
    input  logic [4:0] wb_rd,
    input  logic [4:0] id_ex_rs1,
    input  logic [4:0] id_ex_rs2,
    output logic [1:0] fwd_a_sel,
    output logic [1:0] fwd_b_sel
);

    logic ex_mem_hit_a;
    logic ex_mem_hit_b;
    logic wb_hit_a;
    logic wb_hit_b;

    assign ex_mem_hit_a = ex_mem_valid && ex_mem_reg_write && !ex_mem_mem_read &&
                          (ex_mem_rd != 5'd0) && (ex_mem_rd == id_ex_rs1);
    assign ex_mem_hit_b = ex_mem_valid && ex_mem_reg_write && !ex_mem_mem_read &&
                          (ex_mem_rd != 5'd0) && (ex_mem_rd == id_ex_rs2);

    assign wb_hit_a = wb_we && (wb_rd != 5'd0) && (wb_rd == id_ex_rs1);
    assign wb_hit_b = wb_we && (wb_rd != 5'd0) && (wb_rd == id_ex_rs2);

    always_comb begin
        if (ex_mem_hit_a) begin
            fwd_a_sel = 2'b10;
        end else if (wb_hit_a) begin
            fwd_a_sel = 2'b01;
        end else begin
            fwd_a_sel = 2'b00;
        end

        if (ex_mem_hit_b) begin
            fwd_b_sel = 2'b10;
        end else if (wb_hit_b) begin
            fwd_b_sel = 2'b01;
        end else begin
            fwd_b_sel = 2'b00;
        end
    end

endmodule
